import{_ as t,o as i,c as o,a2 as a}from"./chunks/framework.e4u2V5E7.js";const u=JSON.parse('{"title":"Tailwind Css","description":"Tailwind Css reference documentation","frontmatter":{"title":"Tailwind Css","description":"Tailwind Css reference documentation"},"headers":[],"relativePath":"knowledge/tailwind-css.md","filePath":"knowledge/tailwind-css.md","lastUpdated":1784485118000}'),s={name:"knowledge/tailwind-css.md"};function n(r,e,d,l,c,g){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="tailwind-css" tabindex="-1">Tailwind Css <a class="header-anchor" href="#tailwind-css" aria-label="Permalink to &quot;Tailwind Css&quot;">​</a></h1><h1 id="tailwind-css-3-4-—-knowledge-reference" tabindex="-1">Tailwind CSS 3.4+ — Knowledge Reference <a class="header-anchor" href="#tailwind-css-3-4-—-knowledge-reference" aria-label="Permalink to &quot;Tailwind CSS 3.4+ — Knowledge Reference&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Reference for Tailwind CSS development covering utility-first CSS, responsive design, dark mode, custom themes, plugins, JIT compilation, content configuration, design tokens, and CSS variables integration. Focused on production patterns for scalable design systems.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="utility-first-approach" tabindex="-1">Utility-First Approach <a class="header-anchor" href="#utility-first-approach" aria-label="Permalink to &quot;Utility-First Approach&quot;">​</a></h3><p>Tailwind provides low-level utility classes that compose directly in HTML/JSX. Instead of writing custom CSS, you apply pre-built classes like <code>flex</code>, <code>items-center</code>, <code>text-lg</code>, <code>bg-primary</code>. This eliminates naming debates, reduces CSS bundle size, and keeps styles co-located with markup.</p><h3 id="jit-just-in-time-mode" tabindex="-1">JIT (Just-In-Time) Mode <a class="header-anchor" href="#jit-just-in-time-mode" aria-label="Permalink to &quot;JIT (Just-In-Time) Mode&quot;">​</a></h3><p>JIT is the default engine since Tailwind 3.0. It generates styles on-demand by scanning template files for class usage. Only used utilities are included in the final CSS. Enables arbitrary values (<code>[value]</code>), modifiers, and instant purging without configuration.</p><h3 id="content-configuration" tabindex="-1">Content Configuration <a class="header-anchor" href="#content-configuration" aria-label="Permalink to &quot;Content Configuration&quot;">​</a></h3><p><code>tailwind.config.js</code> requires a <code>content</code> array specifying file paths to scan for class usage. Missing paths result in purged styles. Include all template files: <code>src/**/*.{ts,tsx,js,jsx}</code>.</p><h3 id="responsive-design" tabindex="-1">Responsive Design <a class="header-anchor" href="#responsive-design" aria-label="Permalink to &quot;Responsive Design&quot;">​</a></h3><p>Tailwind uses mobile-first breakpoints: <code>sm:</code> (640px), <code>md:</code> (768px), <code>lg:</code> (1024px), <code>xl:</code> (1280px), <code>2xl:</code> (1536px). Apply base styles for mobile, override at larger screens: <code>md:grid-cols-2 lg:grid-cols-3</code>.</p><h3 id="dark-mode" tabindex="-1">Dark Mode <a class="header-anchor" href="#dark-mode" aria-label="Permalink to &quot;Dark Mode&quot;">​</a></h3><p>Two strategies: <code>class</code> (toggled via a class on <code>&lt;html&gt;</code>, preferred for manual control) and <code>media</code> (follows OS preference). Use the <code>dark:</code> modifier: <code>dark:bg-gray-900 dark:text-white</code>.</p><h3 id="custom-themes" tabindex="-1">Custom Themes <a class="header-anchor" href="#custom-themes" aria-label="Permalink to &quot;Custom Themes&quot;">​</a></h3><p>Extend or override the default theme in <code>tailwind.config.js</code>. Customize colors, spacing, fonts, breakpoints, shadows, and more. Use <code>theme.extend</code> to merge with defaults rather than replacing entirely.</p><h3 id="design-tokens" tabindex="-1">Design Tokens <a class="header-anchor" href="#design-tokens" aria-label="Permalink to &quot;Design Tokens&quot;">​</a></h3><p>Map your design system tokens to Tailwind theme values. Use CSS variables for runtime theming: define tokens in <code>:root</code>, reference them in <code>tailwind.config.js</code> via <code>theme(&#39;colors.primary&#39;)</code> or CSS <code>var()</code> for dynamic theming.</p><h3 id="css-variables-integration" tabindex="-1">CSS Variables Integration <a class="header-anchor" href="#css-variables-integration" aria-label="Permalink to &quot;CSS Variables Integration&quot;">​</a></h3><p>Define custom properties in <code>:root</code> or a theme provider, then reference them in Tailwind config: <code>colors: { primary: &#39;rgb(var(--color-primary) / &lt;alpha-value&gt;)&#39; }</code>. Enables runtime theme switching without rebuilding CSS.</p><h3 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h3><p>Extend Tailwind with custom utilities, components, or preflight modifications. Use <code>@tailwindcss/forms</code> for form reset, <code>@tailwindcss/typography</code> for prose, <code>@tailwindcss/container-queries</code> for container queries. Write custom plugins with <code>plugin()</code> API.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Use <code>@apply</code> sparingly and only for repeated patterns</strong> — utilities in markup are the primary pattern; <code>@apply</code> is for extracted component classes that repeat across many elements</li><li><strong>Extract components via <code>@layer components</code></strong> — define reusable component classes in a dedicated layer to avoid specificity issues with utilities</li><li><strong>Use design tokens as CSS variables</strong> — enables runtime theme switching, reduces config duplication, and integrates with other CSS tools</li><li><strong>Configure <code>content</code> correctly</strong> — missing file paths cause missing styles; use glob patterns and include all template directories</li><li><strong>Use <code>safelist</code> for dynamic classes</strong> — when class names are constructed at runtime (e.g., <code>bg-${color}-500</code>), safelist them to prevent purging</li><li><strong>Leverage <code>theme()</code> function in CSS</strong> — access Tailwind config values in regular CSS: <code>color: theme(&#39;colors.primary.500&#39;)</code></li><li><strong>Use <code>preflight</code> reset wisely</strong> — Tailwind&#39;s preflight normalizes browser defaults; disable if it conflicts with third-party UI libraries</li><li><strong>Organize utilities logically</strong> — follow a consistent ordering: layout → positioning → spacing → typography → visual → interactive</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Using <code>@apply</code> for everything</strong> — defeats the purpose of utility-first CSS; creates large CSS bundles with duplicated utilities</li><li><strong>Hardcoding colors in components</strong> — use theme tokens instead; <code>bg-blue-500</code> should be <code>bg-primary</code> mapped in the theme</li><li><strong>Ignoring the content configuration</strong> — uncanned files produce empty CSS; always verify content paths</li><li><strong>Overriding default theme values</strong> — use <code>theme.extend</code> to keep defaults available; direct overrides lose the entire default palette</li><li><strong>Using arbitrary values excessively</strong> — <code>[width: 237px]</code> indicates the design system is incomplete; add a theme value instead</li><li><strong>Not using responsive prefixes</strong> — desktop-only CSS breaks mobile; design mobile-first and enhance</li><li><strong>Mixing Tailwind with inline styles</strong> — use one approach consistently; inline styles override Tailwind and cannot be purged</li><li><strong>Using <code>!important</code> via <code>!</code> prefix</strong> — <code>!important</code> overrides specificity intentionally; use only when overriding third-party styles</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Forgetting that Tailwind is JIT by default</strong> — no need to configure purge; just ensure content paths are correct</li><li><strong>Confusing <code>sm:</code> with small screens</strong> — <code>sm:</code> means 640px and above, not small screens; it&#39;s the smallest breakpoint, not a mobile override</li><li><strong>Not understanding class order sensitivity</strong> — <code>p-4 m-4</code> vs <code>m-4 p-4</code> produce different results; follow the recommended order</li><li><strong>Using <code>dark:</code> without a dark mode strategy</strong> — must configure <code>darkMode: &#39;class&#39;</code> or <code>&#39;media&#39;</code> in <code>tailwind.config.js</code></li><li><strong>Not purging unused utilities</strong> — without JIT or purging, the full Tailwind CSS is ~3MB; JIT eliminates this by default</li><li><strong>Ignoring the <code>preflight</code> layer</strong> — base styles reset browser defaults; styles that look wrong may be preflight interactions</li><li><strong>Using <code>gap</code> with old browsers</strong> — <code>gap</code> in flexbox requires modern browsers; check caniuse.com for support</li><li><strong>Not leveraging <code>group</code> and <code>peer</code> modifiers</strong> — <code>group-hover:</code> enables parent-triggered child styling without JavaScript</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Approach</th></tr></thead><tbody><tr><td>One-off custom value</td><td>Arbitrary value <code>[value]</code></td></tr><tr><td>Repeated component pattern</td><td><code>@layer components</code> + <code>@apply</code></td></tr><tr><td>Dynamic class names</td><td><code>safelist</code> in config</td></tr><tr><td>Runtime theme switching</td><td>CSS variables + <code>darkMode: &#39;class&#39;</code></td></tr><tr><td>Form styling</td><td><code>@tailwindcss/forms</code> plugin</td></tr><tr><td>Rich text content</td><td><code>@tailwindcss/typography</code> plugin</td></tr><tr><td>Container-aware layouts</td><td><code>@tailwindcss/container-queries</code> plugin</td></tr><tr><td>Design system tokens</td><td>CSS variables in <code>:root</code> + theme config</td></tr><tr><td>Legacy CSS migration</td><td>Incremental <code>@apply</code> extraction</td></tr><tr><td>Responsive grid layout</td><td><code>grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3</code></td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://tailwindcss.com/docs" target="_blank" rel="noreferrer">Tailwind CSS Documentation</a></li><li><a href="https://tailwindcss.com/playground" target="_blank" rel="noreferrer">Tailwind CSS Playground</a></li><li><a href="https://headlessui.com" target="_blank" rel="noreferrer">Headless UI</a> — accessible unstyled components for Tailwind</li><li><a href="https://tailwindui.com" target="_blank" rel="noreferrer">Tailwind UI</a> — official component library</li><li><a href="https://daisyui.com" target="_blank" rel="noreferrer">daisyUI</a> — Tailwind component plugin</li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li>Tailwind CSS 4.0 uses a new Oxide engine with even faster build times and new features; check compatibility before upgrading</li><li><code>tailwind.config.js</code> supports <code>theme()</code> function in CSS for accessing config values</li><li>Use <code>tailwindcss-animate</code> plugin for animation utilities beyond Tailwind&#39;s built-in transitions</li><li>VS Code extension <code>Tailwind CSS IntelliSense</code> provides autocompletion and linting for class names</li><li>For RTL support, combine Tailwind with logical properties (<code>ms-</code>/<code>me-</code> instead of <code>ml-</code>/<code>mr-</code>)</li><li>PostCSS plugins run after Tailwind; configure ordering in <code>postcss.config.js</code> if needed</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',37)])])}const h=t(s,[["render",n]]);export{u as __pageData,h as default};
